import React, { useMemo, useState } from 'react';
import AdminSidebar from '../components/AdminSidebar';

/* Учебный год: сентябрь 2026 – июль 2027 */
const ACADEMIC_YEAR = {
  start: { year: 2026, month: 9 },   // сентябрь
  end: { year: 2027, month: 7 },     // июль
};

const MONTHS_RU = [
  'Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь',
  'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь',
];

const MONTHS_SHORT = ['Янв', 'Фев', 'Мар', 'Апр', 'Май', 'Июн', 'Июл', 'Авг', 'Сен', 'Окт', 'Ноя', 'Дек'];

/* Получить список месяцев учебного года */
const getAcademicMonths = () => {
  const months = [];
  let { year, month } = ACADEMIC_YEAR.start;
  while (year < ACADEMIC_YEAR.end.year || (year === ACADEMIC_YEAR.end.year && month <= ACADEMIC_YEAR.end.month)) {
    months.push({ year, month });
    month++;
    if (month > 12) { month = 1; year++; }
  }
  return months;
};

/* Форматирование даты по Владивостоку */
const formatVladivostokDate = (date) => {
  const formatter = new Intl.DateTimeFormat('ru-RU', {
    timeZone: 'Asia/Vladivostok',
    day: '2-digit',
    month: 'long',
    year: 'numeric',
    weekday: 'long',
  });
  return formatter.format(date);
};

const getVladivostokDate = () => {
  const now = new Date();
  const str = new Intl.DateTimeFormat('ru-RU', {
    timeZone: 'Asia/Vladivostok',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(now);
  const [day, month, year] = str.split('.').map(Number);
  return new Date(year, month - 1, day);
};

/* ---------- Мелкие UI-кусочки ---------- */

const ModalShell = ({ title, onClose, children, wide = false }) => (
  <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#676565]/40 px-5">
    <div className={`w-full ${wide ? 'max-w-[720px]' : 'max-w-[420px]'} rounded-2xl bg-primary p-6 shadow-xl`}>
      <div className="flex items-start justify-between mb-4">
        <h2 className="text-2xl leading-[105%] font-semibold text-black laptop:text-[32px]">{title}</h2>
        <button type="button" aria-label="Закрыть" onClick={onClose} className="p-1 text-gray hover:text-black transition-colors">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M6 6l12 12M18 6L6 18" /></svg>
        </button>
      </div>
      {children}
    </div>
  </div>
);

const FieldLabel = ({ children }) => <p className="mb-2 text-sm font-medium text-black">{children}</p>;

/* ---------- Карточка статистики ---------- */

const StatCard = ({ title, value, subtitle, icon, onClick }) => (
  <button
    type="button"
    onClick={onClick}
    className="group flex flex-col items-start rounded-2xl border border-gray/20 bg-primary p-6 text-left transition-all hover:border-accent hover:shadow-lg"
  >
    <div className="mb-4 flex h-12 w-12 items-center justify-center rounded-xl bg-accent/20 text-black">
      {icon}
    </div>
    <p className="text-sm leading-[120%] text-gray">{title}</p>
    <p className="mt-2 text-3xl font-semibold text-black laptop:text-4xl">{value}</p>
    {subtitle && <p className="mt-1 text-xs leading-[120%] text-gray">{subtitle}</p>}
    <span className="mt-4 text-xs font-medium text-accent opacity-0 transition-opacity group-hover:opacity-100">
      Подробнее →
    </span>
  </button>
);

/* ---------- Модалка «Выбрать дату» ---------- */

const DatePickerModal = ({ selectedDate, onSelect, onClose }) => {
  const academicMonths = useMemo(() => getAcademicMonths(), []);
  const [viewYear, setViewYear] = useState(selectedDate.getFullYear());
  const [viewMonth, setViewMonth] = useState(selectedDate.getMonth() + 1);

  const isSameDay = (a, b) =>
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate();

  const daysInMonth = new Date(viewYear, viewMonth, 0).getDate();
  const firstDayOfWeek = new Date(viewYear, viewMonth - 1, 1).getDay();
  const startOffset = firstDayOfWeek === 0 ? 6 : firstDayOfWeek - 1; // Пн = 0

  const isDateInAcademicYear = (year, month) => {
    if (year < ACADEMIC_YEAR.start.year || year > ACADEMIC_YEAR.end.year) return false;
    if (year === ACADEMIC_YEAR.start.year && month < ACADEMIC_YEAR.start.month) return false;
    if (year === ACADEMIC_YEAR.end.year && month > ACADEMIC_YEAR.end.month) return false;
    return true;
  };

  const prevMonth = () => {
    let m = viewMonth - 1, y = viewYear;
    if (m < 1) { m = 12; y--; }
    if (isDateInAcademicYear(y, m)) { setViewMonth(m); setViewYear(y); }
  };

  const nextMonth = () => {
    let m = viewMonth + 1, y = viewYear;
    if (m > 12) { m = 1; y++; }
    if (isDateInAcademicYear(y, m)) { setViewMonth(m); setViewYear(y); }
  };

  return (
    <ModalShell title="Выбрать дату" onClose={onClose}>
      <div className="mt-4 flex items-center justify-between">
        <button type="button" onClick={prevMonth} className="p-2 text-black hover:text-accent">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M15 18l-6-6 6-6" /></svg>
        </button>
        <p className="text-lg font-semibold text-black">
          {MONTHS_RU[viewMonth - 1]} {viewYear}
        </p>
        <button type="button" onClick={nextMonth} className="p-2 text-black hover:text-accent">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M9 18l6-6-6-6" /></svg>
        </button>
      </div>

      <div className="mt-4 grid grid-cols-7 gap-1 text-center text-xs text-gray">
        {['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'].map((d) => <div key={d} className="py-2">{d}</div>)}
      </div>

      <div className="grid grid-cols-7 gap-1">
        {Array.from({ length: startOffset }).map((_, i) => <div key={`e-${i}`} />)}
        {Array.from({ length: daysInMonth }).map((_, i) => {
          const day = i + 1;
          const date = new Date(viewYear, viewMonth - 1, day);
          const isSelected = isSameDay(date, selectedDate);
          const isToday = isSameDay(date, getVladivostokDate());
          return (
            <button
              key={day}
              type="button"
              onClick={() => onSelect(date)}
              className={`h-10 rounded-lg text-sm transition-colors ${
                isSelected
                  ? 'bg-accent font-medium text-black'
                  : isToday
                    ? 'border border-accent text-black'
                    : 'text-black hover:bg-gray/10'
              }`}
            >
              {day}
            </button>
          );
        })}
      </div>

      <button
        type="button"
        onClick={onClose}
        className="mt-6 h-11 w-full rounded-lg bg-gray/10 text-sm text-gray transition-colors hover:text-black"
      >
        Закрыть
      </button>
    </ModalShell>
  );
};

/* ---------- Модалка «График получения питания» ---------- */

const ScheduleModal = ({ onClose }) => {
  const academicMonths = useMemo(() => getAcademicMonths(), []);

  // Мок: количество порций за каждый месяц (придёт с backend)
  const [monthStats] = useState(() =>
    academicMonths.map((m) => ({
      ...m,
      label: `${MONTHS_RU[m.month - 1]} ${m.year}`,
      count: Math.floor(Math.random() * 3000) + 500,
    }))
  );

  const total = monthStats.reduce((sum, m) => sum + m.count, 0);

  const handleDownloadMonth = (month) => {
    // TODO: GET /api/reports/monthly?year=...&month=... → Excel
    console.log('Скачать отчёт за', month.label);
  };

  const handleDownloadYear = () => {
    // TODO: GET /api/reports/academic-year?year=2026-2027 → Excel
    console.log('Скачать отчёт за учебный год');
  };

  return (
    <ModalShell title="График получения питания" onClose={onClose} wide>
      <div className="mt-4 flex items-center justify-between rounded-xl bg-gray/10 px-4 py-3">
        <div>
          <p className="text-sm text-gray">Учебный год</p>
          <p className="text-lg font-semibold text-black">Сентябрь 2026 – Июль 2027</p>
        </div>
        <div className="text-right">
          <p className="text-sm text-gray">Всего порций</p>
          <p className="text-lg font-semibold text-black">{total}</p>
        </div>
      </div>

      <div className="mt-4 max-h-[400px] overflow-y-auto">
        <table className="w-full text-left">
          <thead className="sticky top-0 bg-primary">
            <tr className="border-b border-gray/20">
              <th className="px-4 py-3 text-sm font-medium text-black">Месяц</th>
              <th className="px-4 py-3 text-sm font-medium text-black">Порций</th>
              <th className="px-4 py-3 text-sm font-medium text-black text-right">Действие</th>
            </tr>
          </thead>
          <tbody>
            {monthStats.map((m) => (
              <tr key={`${m.year}-${m.month}`} className="border-b border-gray/10">
                <td className="px-4 py-3 text-sm text-black">{m.label}</td>
                <td className="px-4 py-3 text-sm text-black">{m.count}</td>
                <td className="px-4 py-3 text-right">
                  <button
                    type="button"
                    onClick={() => handleDownloadMonth(m)}
                    className="inline-flex items-center gap-2 rounded-lg bg-accent px-4 py-2 text-xs font-medium text-black transition-colors hover:bg-accent/90"
                  >
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M12 15V5 M8 8l4-4 4 4 M4 17v2h16v-2" /></svg>
                    Excel
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="mt-6 grid grid-cols-2 gap-3">
        <button type="button" onClick={onClose} className="h-11 rounded-lg bg-gray/10 text-sm text-gray transition-colors hover:text-black">
          Закрыть
        </button>
        <button
          type="button"
          onClick={handleDownloadYear}
          className="flex h-11 items-center justify-center gap-2 rounded-lg bg-accent text-sm font-medium text-black transition-colors hover:bg-accent/90"
        >
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M12 15V5 M8 8l4-4 4 4 M4 17v2h16v-2" /></svg>
          Скачать за учебный год
        </button>
      </div>
    </ModalShell>
  );
};

/* ---------- Модалка детализации (общая для 4 карточек) ---------- */

const DetailModal = ({ title, rows, onClose }) => (
  <ModalShell title={title} onClose={onClose} wide>
    <div className="mt-4 max-h-[480px] overflow-y-auto">
      <table className="w-full text-left">
        <thead className="sticky top-0 bg-primary">
          <tr className="border-b border-gray/20">
            {Object.keys(rows[0] ?? {}).map((key) => (
              <th key={key} className="px-4 py-3 text-sm font-medium text-black">{key}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, idx) => (
            <tr key={idx} className="border-b border-gray/10">
              {Object.values(row).map((val, i) => (
                <td key={i} className="px-4 py-3 text-sm text-black">{val}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
    <button
      type="button"
      onClick={onClose}
      className="mt-6 h-11 w-full rounded-lg bg-gray/10 text-sm text-gray transition-colors hover:text-black"
    >
      Закрыть
    </button>
  </ModalShell>
);

/* ---------- Страница ---------- */

const DashboardReports = () => {
  const [selectedDate, setSelectedDate] = useState(getVladivostokDate());

  // Модалки
  const [datePickerOpen, setDatePickerOpen] = useState(false);
  const [scheduleOpen, setScheduleOpen] = useState(false);
  const [detailModal, setDetailModal] = useState(null); // { title, rows }

  // Мок данных за выбранный день (придёт с backend)
  const dayStats = useMemo(() => ({
    totalPortions: 342,
    studentsWithMeals: 287,
    groupsCount: 14,
    topGroup: { name: '18-116', portions: 28 },
  }), [selectedDate]);

  // Мок детализации
  const mockPortions = Array.from({ length: 20 }).map((_, i) => ({
    'Время': `${8 + Math.floor(i / 4)}:${String((i % 4) * 15).padStart(2, '0')}`,
    'ФИО': `Студент ${i + 1} Иванов`,
    'Группа': `${10 + (i % 5)}-116`,
    'Категория': ['Общежитие', 'Соцгруппа', 'Специальность'][i % 3],
  }));

  const mockStudents = Array.from({ length: 15 }).map((_, i) => ({
    'ФИО': `Студент ${i + 1} Иванов`,
    'Группа': `${10 + (i % 5)}-116`,
    'Порций': (i % 3) + 1,
  }));

  const mockGroups = Array.from({ length: 10 }).map((_, i) => ({
    'Группа': `${10 + i}-116`,
    'Студентов': Math.floor(Math.random() * 20) + 10,
    'Порций': Math.floor(Math.random() * 30) + 15,
  }));

  const mockTopGroup = Array.from({ length: 28 }).map((_, i) => ({
    'ФИО': `Студент ${i + 1} Иванов`,
    'Порций': (i % 3) + 1,
    'Время': `${12 + Math.floor(i / 4)}:${String((i % 4) * 15).padStart(2, '0')}`,
  }));

  const formattedDate = formatVladivostokDate(selectedDate);

  const handleDownloadDay = () => {
    // TODO: GET /api/reports/daily?date=YYYY-MM-DD → Excel
    console.log('Скачать отчёт за', selectedDate.toISOString().split('T')[0]);
  };

  return (
    <div className="min-h-screen w-full bg-secondary flex">
      <AdminSidebar active="reports" />

      <main className="flex-1 overflow-x-hidden px-5 py-8 laptop:px-10">
        {/* Заголовок */}
        <h1 className="text-4xl leading-[105%] font-semibold text-black laptop:text-[40px] desktop:text-[32px]">
          Отчёты
        </h1>
        <p className="mt-1 text-sm leading-[120%] text-gray">Статистика выдачи питания</p>

        {/* Панель даты */}
        <div className="mt-6 flex flex-wrap items-center gap-4">
          <div className="flex items-center gap-3 rounded-xl bg-primary px-5 py-3">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" className="text-accent">
              <rect x="3" y="5" width="18" height="16" rx="2" />
              <path d="M8 3v4 M16 3v4 M3 10h18" />
            </svg>
            <div>
              <p className="text-xs text-gray">Дата отчёта (Владивосток)</p>
              <p className="text-sm font-medium capitalize text-black">{formattedDate}</p>
            </div>
          </div>

          <button
            type="button"
            onClick={() => setDatePickerOpen(true)}
            className="flex h-11 items-center gap-2 rounded-lg border border-gray/40 bg-transparent px-5 text-sm font-medium text-black transition-colors hover:border-black"
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M12 20v-6 M2 12l2-2m0 0l7-7 7 7m-7-7v18" /></svg>
            Изменить дату
          </button>

          <button
            type="button"
            onClick={handleDownloadDay}
            className="flex h-11 items-center gap-2 rounded-lg bg-accent px-5 text-sm font-medium text-black transition-colors hover:bg-accent/90"
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M12 15V5 M8 8l4-4 4 4 M4 17v2h16v-2" /></svg>
