          </button>
        </div>

        {/* Карточки статистики */}
        <div className="mt-8 grid grid-cols-1 gap-4 sm:grid-cols-2 laptop:grid-cols-4">
          <StatCard
            title="Всего порций выдано"
            value={dayStats.totalPortions}
            subtitle="за выбранный день"
            icon={
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M3 11h18 M5 11V7a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v4 M7 11v8a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-8" /></svg>
            }
            onClick={() => setDetailModal({ title: 'Всего порций выдано', rows: mockPortions })}
          />
          <StatCard
            title="Студенты с питанием"
            value={dayStats.studentsWithMeals}
            subtitle="уникальных студентов"
            icon={
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M23 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75" /></svg>
            }
            onClick={() => setDetailModal({ title: 'Студенты с питанием', rows: mockStudents })}
          />
          <StatCard
            title="Кол-во групп"
            value={dayStats.groupsCount}
            subtitle="групп пообедали"
            icon={
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M12 6c-2-1.5-4.5-2-8-2v14c3.5 0 6 .5 8 2 2-1.5 4.5-2 8-2V4c-3.5 0-6 .5-8 2Z" /></svg>
            }
            onClick={() => setDetailModal({ title: 'Кол-во групп', rows: mockGroups })}
          />
          <StatCard
            title="Группа «Прожор»"
            value={dayStats.topGroup.name}
            subtitle={`${dayStats.topGroup.portions} порций — лидер дня`}
            icon={
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" /></svg>
            }
            onClick={() => setDetailModal({ title: `Группа «Прожор»: ${dayStats.topGroup.name}`, rows: mockTopGroup })}
          />
        </div>

        {/* Подсказка */}
        <p className="mt-6 text-center text-xs text-gray">
          Нажмите на карточку, чтобы увидеть детальный отчёт
        </p>
      </main>

      {/* ---------- Модалки ---------- */}

      {datePickerOpen && (
        <DatePickerModal
          selectedDate={selectedDate}
          onSelect={(d) => { setSelectedDate(d); setDatePickerOpen(false); }}
          onClose={() => setDatePickerOpen(false)}
        />
      )}

      {scheduleOpen && <ScheduleModal onClose={() => setScheduleOpen(false)} />}

      {detailModal && (
        <DetailModal
          title={detailModal.title}
          rows={detailModal.rows}
          onClose={() => setDetailModal(null)}
        />
      )}
    </div>
  );
};

export default DashboardReports;
